145	type backupV1 struct {
146		Version    int                   `json:"version"`
147		ExportedAt timeJSON              `json:"exported_at"`
148		Accounts   []accountBackupV1     `json:"accounts"`
149		Sessions   []sessionBackupV1     `json:"sessions"`
150		Policies   []policyBackupV1      `json:"policies"`
151		Requests   []requestBackupV1     `json:"requests"`
152		Ledger     []ledgerEntryBackupV1 `json:"ledger"`
153	}
154	
155	// Export 将当前钱包导出为带版本号的 JSON 文本。
156	//
157	// 导出在钱包同一把全局锁内完成，对应某一时刻的完整状态：可与申请、
158	// 批准、拒绝、吊销、停用、结算或取消并发，不会出现只有余额变化却缺少
159	// 对应请求或账本的半截状态。导出前先按导出时的当前时间处理全部到期
160	// 请求——待审批到达等待截止时刻后进入过期终态并留痕，已预留到达预留
161	// 截止时刻后全额退回（释放时间仍为原截止时刻）并留下退款及超时记录；
162	// 未到期请求继续等待或预留。
163	//
164	// 备份保留账户余额、会话的设备绑定与吊销状态、策略条件及停用信息、
165	// 全部请求的申请内容、状态、审批决定与全部计时信息，以及按原顺序排列
166	// 的账本（包括未被受理申请的拒绝记录）。空钱包也能导出并恢复；导出
167	// 本身不新增任何账本记录（到期处理带来的记录除外）。
168	//
169	// 备份不能暂停期限，因此导出不改变任何请求的计时基准；导出后的钱包
170	// 与备份文本、以及从该备份恢复出的钱包之间互不影响。
171	func (w *Wallet) Export() ([]byte, error) {
172		w.mu.Lock()
173		defer w.mu.Unlock()
174	
175		now := w.now()
176		// 导出快照前结清全部到期项，保证备份对应一个完整状态：已预留超时的按
177		// 原截止时刻全额退回并留两条记录（按截止时刻排序），待审批过期的留
178		// 状态记录（按等待截止时刻排序）。
179		w.expireReservationsLocked(now)
180		w.expirePendingApprovalsLocked(now)
181	
182		b := backupV1{
183			Version:    backupVersion,
184			ExportedAt: timeJSON(now),
185			Accounts:   make([]accountBackupV1, 0, len(w.accounts)),
186			Sessions:   make([]sessionBackupV1, 0, len(w.sessions)),
187			Policies:   make([]policyBackupV1, 0, len(w.policies)),
188			Requests:   make([]requestBackupV1, 0, len(w.requests)),
189			Ledger:     make([]ledgerEntryBackupV1, 0, len(w.ledger)),
190		}
191	
192		// map 迭代顺序不确定；集合类数据按编号排序，使备份可逐字节复现。
193		for _, a := range w.accounts {
194			b.Accounts = append(b.Accounts, accountBackupV1{
195				ID:        a.id,
196				Available: a.available,
197				Reserved:  a.reserved,
198				CreatedAt: timeJSON(a.createdAt),
199			})
200		}
201		sort.Slice(b.Accounts, func(i, j int) bool { return b.Accounts[i].ID < b.Accounts[j].ID })
202	
203		for _, s := range w.sessions {
204			b.Sessions = append(b.Sessions, sessionBackupV1{
205				ID:        s.id,
206				AccountID: s.accountID,
207				DeviceID:  s.deviceID,
208				ExpiresAt: timeJSON(s.expiresAt),
209				Revoked:   s.revoked,
210				CreatedAt: timeJSON(s.createdAt),
211			})
212		}
213		sort.Slice(b.Sessions, func(i, j int) bool { return b.Sessions[i].ID < b.Sessions[j].ID })
214	
215		for _, p := range w.policies {
216			allowed := make([]string, 0, len(p.allowedAccounts))
217			for id := range p.allowedAccounts {
218				allowed = append(allowed, id)
219			}
220			sort.Strings(allowed)
221			b.Policies = append(b.Policies, policyBackupV1{
222				ID:                   p.id,
223				PayerAccountID:       p.payerAccountID,
224				AllowedAccountIDs:    allowed,
225				Operation:            p.operation,
226				Payee:                p.payee,
227				StartsAt:             timeJSON(p.startsAt),
228				EndsAt:               timeJSON(p.endsAt),
229				MaxPerRequest:        p.maxPerRequest,
230				MaxTotal:             p.maxTotal,
231				ApprovalThreshold:    p.approvalThreshold,
232				ApprovalWait:         durationJSON(p.approvalWait),
233				MaxReserveDuration:   durationJSON(p.maxReserveDuration),
234				ReservedTotal:        p.reservedTotal,
235				SpentTotal:           p.spentTotal,
236				Deactivated:          p.deactivated,
237				DeactivatedAt:        timeJSON(p.deactivatedAt),
238				DeactivatorAccountID: p.deactivatorAccountID,
239				DeactivateReason:     p.deactivateReason,
240			})
241		}
242		sort.Slice(b.Policies, func(i, j int) bool { return b.Policies[i].ID < b.Policies[j].ID })
243	
244		for _, r := range w.requests {
245			b.Requests = append(b.Requests, requestBackupV1{
246				PolicyID:          r.policyID,
247				RequestID:         r.requestID,
248				AccountID:         r.accountID,
249				PayerAccountID:    r.payerAccountID,
250				SessionID:         r.sessionID,
251				Operation:         r.operation,
252				Payee:             r.payee,
253				EstimatedFee:      r.estimatedFee,
254				ActualFee:         r.actualFee,
255				State:             int(r.state),
256				CreatedAt:         timeJSON(r.createdAt),
257				SettledAt:         timeJSON(r.settledAt),
258				WaitDeadline:      timeJSON(r.waitDeadline),
259				ReservedAt:        timeJSON(r.reservedAt),
260				ReserveDuration:   durationJSON(r.reserveDuration),
261				ReserveDeadline:   timeJSON(r.reserveDeadline),
262				ReserveExpiredAt:  timeJSON(r.reserveExpiredAt),
263				DecidedAt:         timeJSON(r.decidedAt),
264				ApproverAccountID: r.approverAccountID,
265				RejectReason:      r.rejectReason,
266			})
267		}
268		sort.Slice(b.Requests, func(i, j int) bool {
269			if b.Requests[i].AccountID != b.Requests[j].AccountID {
270				return b.Requests[i].AccountID < b.Requests[j].AccountID
271			}
272			return b.Requests[i].RequestID < b.Requests[j].RequestID
273		})
274	
275		// 账本严格按原顺序导出，不重新排序。
276		for _, e := range w.ledger {
277			b.Ledger = append(b.Ledger, ledgerEntryBackupV1{
278				Kind:      int(e.Kind),
279				AccountID: e.AccountID,
280				RequestID: e.RequestID,
281				PolicyID:  e.PolicyID,
282				Amount:    e.Amount,
283				Reason:    e.Reason,
284				At:        timeJSON(e.At),
285			})
286		}
287	
288		out, err := json.Marshal(&b)
289		if err != nil {
290			return nil, fmt.Errorf("%w: encode: %v", ErrBackupInvalid, err)
291		}
292		return out, nil
293	}
294	
295	// addInt64 在求和时检测 int64 溢出；超出范围返回 false。
296	func addInt64(sum, x int64) (int64, bool) {
297		if x > 0 && sum > math.MaxInt64-x {
298			return 0, false
299		}
300		if x < 0 && sum < math.MinInt64-x {
301			return 0, false
302		}
303		return sum + x, true
304	}
305	
306	// Restore 从 Export 产生的 JSON 文本创建一个独立的钱包。
307	//
308	// 恢复不重新计时：所有截止时刻与会话到期时间沿用备份中的绝对时刻，
309	// 恢复前先按恢复时的当前时间处理全部到期请求（待审批过期、已预留超时
310	// 全额退回，释放时间仍为原截止时刻）。既有终态与历史记录不改写；过期或
311	// 吊销的会话、停用或结束的策略可以恢复，但不会重新获得授权。恢复后被
312	// 超时退回的余额可立即用于新申请，旧请求的迟到结算不能再扣走这笔钱。
313	//
314	// 空文本、非法 JSON、缺少必需数据、不支持的版本、编号重复、未知状态或
315	// 账本类型、非法金额或策略参数、悬空引用、申请会话不属于使用账户、
316	// 请求出资账户与策略不符，或余额/累计金额与请求求和不一致（含求和超出
317	// int64 范围），都返回包装了具体原因的 ErrBackupInvalid，绝不会返回
318	// 部分恢复的钱包。恢复出的钱包与原钱包、同一备份恢复出的其他钱包互不
319	// 影响。
320	func Restore(data []byte) (*Wallet, error) {
321		if len(bytes.TrimSpace(data)) == 0 {
322			return nil, fmt.Errorf("%w: empty backup", ErrBackupInvalid)
323		}
324	
325		var b backupV1
326		dec := json.NewDecoder(bytes.NewReader(data))
327		if err := dec.Decode(&b); err != nil {
328			return nil, fmt.Errorf("%w: malformed json: %v", ErrBackupInvalid, err)
329		}
330		// 不允许备份对象之后还有多余的 JSON 值；忽略空白。
331		if _, err := dec.Token(); err != io.EOF {
332			return nil, fmt.Errorf("%w: unexpected trailing data after backup object", ErrBackupInvalid)
333		}
334		if b.Version != backupVersion {
335			return nil, fmt.Errorf("%w: unsupported version %d (supported: %d)", ErrBackupInvalid, b.Version, backupVersion)
336		}
337	
338		w := New()
339		if err := w.restoreLocked(&b); err != nil {
340			return nil, err
341		}
342		return w, nil
343	}
344	
345	// restoreAt 仅供同包测试使用：与 Restore 相同，但显式指定恢复时刻，
346	// 便于确定性地验证恢复时的到期处理。
347	func restoreAt(data []byte, now time.Time) (*Wallet, error) {
348		if len(bytes.TrimSpace(data)) == 0 {
349			return nil, fmt.Errorf("%w: empty backup", ErrBackupInvalid)
350		}
351		var b backupV1
352		dec := json.NewDecoder(bytes.NewReader(data))
353		if err := dec.Decode(&b); err != nil {
354			return nil, fmt.Errorf("%w: malformed json: %v", ErrBackupInvalid, err)
355		}
356		if _, err := dec.Token(); err != io.EOF {
357			return nil, fmt.Errorf("%w: unexpected trailing data after backup object", ErrBackupInvalid)
358		}
359		if b.Version != backupVersion {
360			return nil, fmt.Errorf("%w: unsupported version %d (supported: %d)", ErrBackupInvalid, b.Version, backupVersion)
361		}
362		w := New()
363		w.now = func() time.Time { return now }
364		if err := w.restoreLocked(&b); err != nil {
365			return nil, err
366		}
367		return w, nil
368	}
369	
370	// restoreLocked 逐段构建并校验新钱包；任何失败都返回错误，调用方因此
371	// 绝不会拿到部分恢复的钱包。
372	func (w *Wallet) restoreLocked(b *backupV1) error {
373		// ---- 账户 ----
374		if b.Accounts == nil {
375			return fmt.Errorf("%w: missing accounts", ErrBackupInvalid)
376		}
377		accountIDs := make(map[string]struct{}, len(b.Accounts))
378		reservedByAccount := make(map[string]int64)
379		for i, a := range b.Accounts {
380			if a.ID == "" {
381				return fmt.Errorf("%w: account[%d] has empty id", ErrBackupInvalid, i)
382			}
383			if _, dup := accountIDs[a.ID]; dup {
384				return fmt.Errorf("%w: duplicate account id %q", ErrBackupInvalid, a.ID)
385			}
386			if a.Available < 0 {
387				return fmt.Errorf("%w: account %q available balance is negative: %d", ErrBackupInvalid, a.ID, a.Available)
388			}
389			if a.Reserved < 0 {
390				return fmt.Errorf("%w: account %q reserved balance is negative: %d", ErrBackupInvalid, a.ID, a.Reserved)
391			}
392			accountIDs[a.ID] = struct{}{}
393			w.accounts[a.ID] = &account{
394				id:        a.ID,
395				available: a.Available,
396				reserved:  a.Reserved,
397				createdAt: a.CreatedAt.std(),
398			}
399		}
400	
401		// ---- 会话 ----
402		if b.Sessions == nil {
403			return fmt.Errorf("%w: missing sessions", ErrBackupInvalid)
404		}
405		sessionByID := make(map[string]*session, len(b.Sessions))
406		for i, s := range b.Sessions {
407			if s.ID == "" {
408				return fmt.Errorf("%w: session[%d] has empty id", ErrBackupInvalid, i)
409			}
410			if _, dup := sessionByID[s.ID]; dup {
411				return fmt.Errorf("%w: duplicate session id %q", ErrBackupInvalid, s.ID)
412			}
413			if s.AccountID == "" || s.DeviceID == "" {
414				return fmt.Errorf("%w: session %q missing account or device id", ErrBackupInvalid, s.ID)
415			}
416			if _, ok := accountIDs[s.AccountID]; !ok {
417				return fmt.Errorf("%w: session %q references unknown account %q", ErrBackupInvalid, s.ID, s.AccountID)
418			}
419			sess := &session{
420				id:        s.ID,
421				accountID: s.AccountID,
422				deviceID:  s.DeviceID,
423				expiresAt: s.ExpiresAt.std(),
424				revoked:   s.Revoked,
425				createdAt: s.CreatedAt.std(),
426			}
427			sessionByID[s.ID] = sess
428			w.sessions[s.ID] = sess
429		}
430	
431		// ---- 策略 ----
432		if b.Policies == nil {
433			return fmt.Errorf("%w: missing policies", ErrBackupInvalid)
434		}
435		policyByID := make(map[string]*policy, len(b.Policies))
436		for i, p := range b.Policies {
437			if p.ID == "" {
438				return fmt.Errorf("%w: policy[%d] has empty id", ErrBackupInvalid, i)
439			}
440			if _, dup := policyByID[p.ID]; dup {
441				return fmt.Errorf("%w: duplicate policy id %q", ErrBackupInvalid, p.ID)
442			}
443			if err := validatePolicyParams(p); err != nil {
444				return fmt.Errorf("%w: policy %q: %v", ErrBackupInvalid, p.ID, err)
445			}
446			if _, ok := accountIDs[p.PayerAccountID]; !ok {
447				return fmt.Errorf("%w: policy %q references unknown payer account %q", ErrBackupInvalid, p.ID, p.PayerAccountID)
448			}
449			allowed := make(map[string]struct{}, len(p.AllowedAccountIDs))
450			for j, id := range p.AllowedAccountIDs {
451				if id == "" {
452					return fmt.Errorf("%w: policy %q allowed account[%d] is empty", ErrBackupInvalid, p.ID, j)
453				}
454				if _, ok := accountIDs[id]; !ok {
455					return fmt.Errorf("%w: policy %q references unknown allowed account %q", ErrBackupInvalid, p.ID, id)
456				}
457				if _, dup := allowed[id]; dup {
458					return fmt.Errorf("%w: policy %q lists allowed account %q more than once", ErrBackupInvalid, p.ID, id)
459				}
460				allowed[id] = struct{}{}
461			}
462			if p.ReservedTotal < 0 || p.SpentTotal < 0 {
463				return fmt.Errorf("%w: policy %q totals must not be negative (reserved %d spent %d)", ErrBackupInvalid, p.ID, p.ReservedTotal, p.SpentTotal)
464			}
465			po := &policy{
466				id:                   p.ID,
467				payerAccountID:       p.PayerAccountID,
468				allowedAccounts:      allowed,
469				operation:            p.Operation,
470				payee:                p.Payee,
471				startsAt:             p.StartsAt.std(),
472				endsAt:               p.EndsAt.std(),
473				maxPerRequest:        p.MaxPerRequest,
474				maxTotal:             p.MaxTotal,
475				approvalThreshold:    p.ApprovalThreshold,
476				approvalWait:         p.ApprovalWait.std(),
477				maxReserveDuration:   p.MaxReserveDuration.std(),
478				reservedTotal:        p.ReservedTotal,
479				spentTotal:           p.SpentTotal,
480				deactivated:          p.Deactivated,
481				deactivatedAt:        p.DeactivatedAt.std(),
482				deactivatorAccountID: p.DeactivatorAccountID,
483				deactivateReason:     p.DeactivateReason,
484			}
485			// 停用信息自洽：停用标志必须与停用时间/理由同时出现；停用账户必须
486			// 存在；未停用不得携带任何停用记录。
487			if po.deactivated {
488				if po.deactivatedAt.IsZero() || po.deactivateReason == "" {
489					return fmt.Errorf("%w: policy %q marked deactivated but missing deactivation time or reason", ErrBackupInvalid, p.ID)
490				}
491				if po.deactivatorAccountID != "" {
492					if _, ok := accountIDs[po.deactivatorAccountID]; !ok {
493						return fmt.Errorf("%w: policy %q deactivator references unknown account %q", ErrBackupInvalid, p.ID, po.deactivatorAccountID)
494					}
495				}
496			} else if !po.deactivatedAt.IsZero() || po.deactivatorAccountID != "" || po.deactivateReason != "" {
497				return fmt.Errorf("%w: policy %q not deactivated but carries deactivation info", ErrBackupInvalid, p.ID)
498			}
499			policyByID[p.ID] = po
500			w.policies[p.ID] = po
501		}
502	
503		// ---- 请求 ----
504		if b.Requests == nil {
505			return fmt.Errorf("%w: missing requests", ErrBackupInvalid)
506		}
507		reqKeys := make(map[requestKey]struct{}, len(b.Requests))
508		reservedSumByPolicy := make(map[string]int64)
509		spentSumByPolicy := make(map[string]int64)
510		for i, r := range b.Requests {
511			if err := validateRequestRef(r, i, accountIDs, sessionByID, policyByID); err != nil {
512				return err
513			}
514			key := requestKey{accountID: r.AccountID, requestID: r.RequestID}
515			if _, dup := reqKeys[key]; dup {
516				return fmt.Errorf("%w: duplicate request id %q under account %q", ErrBackupInvalid, r.RequestID, r.AccountID)
517			}
518			reqKeys[key] = struct{}{}
519	
520			state := RequestState(r.State)
521			if state < RequestReserved || state > RequestReservationExpired {
522				return fmt.Errorf("%w: request %q/%q has unknown state %d", ErrBackupInvalid, r.AccountID, r.RequestID, r.State)
523			}
524			if r.EstimatedFee <= 0 {
525				return fmt.Errorf("%w: request %q/%q estimated fee must be positive: %d", ErrBackupInvalid, r.AccountID, r.RequestID, r.EstimatedFee)
526			}
527			if r.ActualFee < 0 {
528				return fmt.Errorf("%w: request %q/%q actual fee is negative: %d", ErrBackupInvalid, r.AccountID, r.RequestID, r.ActualFee)
529			}
530			if r.ReserveDuration.std() < 0 {
531				return fmt.Errorf("%w: request %q/%q reserve duration is negative", ErrBackupInvalid, r.AccountID, r.RequestID)
532			}
533	
534			req := &request{
535				policyID:          r.PolicyID,
536				requestID:         r.RequestID,
537				accountID:         r.AccountID,
538				payerAccountID:    r.PayerAccountID,
539				sessionID:         r.SessionID,
540				operation:         r.Operation,
541				payee:             r.Payee,
542				estimatedFee:      r.EstimatedFee,
543				actualFee:         r.ActualFee,
544				state:             state,
545				createdAt:         r.CreatedAt.std(),
546				settledAt:         r.SettledAt.std(),
547				waitDeadline:      r.WaitDeadline.std(),
548				reservedAt:        r.ReservedAt.std(),
549				reserveDuration:   r.ReserveDuration.std(),
550				reserveDeadline:   r.ReserveDeadline.std(),
551				reserveExpiredAt:  r.ReserveExpiredAt.std(),
552				decidedAt:         r.DecidedAt.std(),
553				approverAccountID: r.ApproverAccountID,
554				rejectReason:      r.RejectReason,
555			}
556			if err := validateRequestTimingAndState(req, policyByID[r.PolicyID], sessionByID[r.SessionID]); err != nil {
557				return fmt.Errorf("%w: request %q/%q: %v", ErrBackupInvalid, r.AccountID, r.RequestID, err)
558			}
559			w.requests[key] = req
560	
561			// 累加各账户/策略“按请求推算”的金额，稍后与快照余额核对。
562			// 只有当前仍处于已预留的请求才占用账户预留与策略预留总额。
563			if state == RequestReserved {
564				sum, ok := addInt64(reservedByAccount[req.payerAccountID], req.estimatedFee)
565				if !ok {
566					return fmt.Errorf("%w: account %q reserved sum overflows int64", ErrBackupInvalid, req.payerAccountID)
567				}
568				reservedByAccount[req.payerAccountID] = sum
569				sum, ok = addInt64(reservedSumByPolicy[req.policyID], req.estimatedFee)
570				if !ok {
571					return fmt.Errorf("%w: policy %q reserved sum overflows int64", ErrBackupInvalid, req.policyID)
572				}
573				reservedSumByPolicy[req.policyID] = sum
574			}
575			if state == RequestSettled {
576				sum, ok := addInt64(spentSumByPolicy[req.policyID], req.actualFee)
577				if !ok {
578					return fmt.Errorf("%w: policy %q spent sum overflows int64", ErrBackupInvalid, req.policyID)
579				}
580				spentSumByPolicy[req.policyID] = sum
581			}
582		}
583	
584		// ---- 账户预留余额 == 已预留请求预估费用之和 ----
585		for id, acc := range w.accounts {
586			if got, want := acc.reserved, reservedByAccount[id]; got != want {
587				return fmt.Errorf("%w: account %q reserved %d != sum of reserved requests %d", ErrBackupInvalid, id, got, want)
588			}
589		}
590	
591		// ---- 策略预留总额/已花费总额 == 请求求和 ----
592		for id, p := range policyByID {
593			if got, want := p.reservedTotal, reservedSumByPolicy[id]; got != want {
594				return fmt.Errorf("%w: policy %q reserved total %d != sum of reserved requests %d", ErrBackupInvalid, id, got, want)
595			}
596			if got, want := p.spentTotal, spentSumByPolicy[id]; got != want {
597				return fmt.Errorf("%w: policy %q spent total %d != sum of settled requests %d", ErrBackupInvalid, id, got, want)
598			}
599		}
600	
601		// ---- 账本 ----
602		if b.Ledger == nil {
603			return fmt.Errorf("%w: missing ledger", ErrBackupInvalid)
604		}
605		w.ledger = make([]LedgerEntry, 0, len(b.Ledger))
606		for i, e := range b.Ledger {
607			kind := LedgerKind(e.Kind)
608			if kind < LedgerReserve || kind > LedgerReservationExpiration {
609				return fmt.Errorf("%w: ledger[%d] has unknown kind %d", ErrBackupInvalid, i, e.Kind)
610			}
611			if e.Amount < 0 {
612				return fmt.Errorf("%w: ledger[%d] amount is negative: %d", ErrBackupInvalid, i, e.Amount)
613			}
614			// 账本是历史留痕：其账户/请求编号允许为空或指向不存在的实体。
615			// 未被受理申请（必填字段缺失、使用账户或会话不存在等）同样会留下
616			// 拒绝记录，这些记录必须原样保留，不能因为找不到对应账户或请求而
617			// 丢弃或拒绝恢复。资金一致性由账户余额与现存请求的求和核对保证，
618			// 不依赖账本文本。PolicyID 若给出则必须存在（仅策略停用记录使用）。
619			if e.PolicyID != "" {
620				if _, ok := policyByID[e.PolicyID]; !ok {
621					return fmt.Errorf("%w: ledger[%d] references unknown policy %q", ErrBackupInvalid, i, e.PolicyID)
622				}
623			}
624			w.ledger = append(w.ledger, LedgerEntry{
625				Kind:      kind,
626				AccountID: e.AccountID,
627				RequestID: e.RequestID,
628				PolicyID:  e.PolicyID,
629				Amount:    e.Amount,
630				Reason:    e.Reason,
631				At:        e.At.std(),
632			})
633		}
634	
635		// ---- 恢复时按当前时间结清到期请求（不重新计时，只推进惰性状态） ----
636		// 处理顺序与导出保持一致：先释放已到期预留，再把到期的待审批转为过期，
637		// 两类记录均按各自截止时刻排序后追加到账本末尾。
638		now := w.now()
639		w.expireReservationsLocked(now)
640		w.expirePendingApprovalsLocked(now)
641		return nil
642	}
643	
644	// validatePolicyParams 校验策略条件与限额参数，规则与 SavePolicy 一致。
645	func validatePolicyParams(p policyBackupV1) error {
646		if p.Operation == "" || p.Payee == "" {
647			return errors.New("operation and payee are required")
648		}
649		if p.MaxPerRequest <= 0 || p.MaxTotal <= 0 {
650			return errors.New("limits must be positive")
651		}
652		if p.ApprovalThreshold < 0 {
653			return errors.New("approval threshold must not be negative")
654		}
655		if p.ApprovalThreshold > 0 {
656			if p.ApprovalThreshold > p.MaxPerRequest {
657				return fmt.Errorf("approval threshold %d exceeds per-request limit %d", p.ApprovalThreshold, p.MaxPerRequest)
658			}
659			if p.ApprovalWait <= 0 {
660				return errors.New("approval wait must be positive when approval is enabled")
661			}
662		}
663		if p.ApprovalWait < 0 || p.MaxReserveDuration < 0 {
664			return errors.New("durations must not be negative")
665		}
666		if !p.StartsAt.std().Before(p.EndsAt.std()) {
667			return errors.New("starts-at must be before ends-at")
668		}
669		if p.PayerAccountID == "" || len(p.AllowedAccountIDs) == 0 {
670			return errors.New("payer account and at least one allowed account are required")
671		}
672		return nil
673	}
674	
675	// validateRequestRef 校验请求的外键引用：账户、会话、策略均须存在；申请
676	// 会话必须属于使用账户；出资账户必须与策略一致；申请账户必须被策略允许。
677	func validateRequestRef(r requestBackupV1, i int, accounts map[string]struct{}, sessions map[string]*session, policies map[string]*policy) error {
678		where := fmt.Sprintf("request[%d] %q/%q", i, r.AccountID, r.RequestID)
679		if r.RequestID == "" || r.AccountID == "" || r.PolicyID == "" || r.SessionID == "" {
680			return fmt.Errorf("%w: %s missing required id (account/request/policy/session)", ErrBackupInvalid, where)
681		}
682		if _, ok := accounts[r.AccountID]; !ok {
683			return fmt.Errorf("%w: %s references unknown usage account %q", ErrBackupInvalid, where, r.AccountID)
684		}
685		if _, ok := accounts[r.PayerAccountID]; !ok {
686			return fmt.Errorf("%w: %s references unknown payer account %q", ErrBackupInvalid, where, r.PayerAccountID)
687		}
688		sess, ok := sessions[r.SessionID]
689		if !ok {
690			return fmt.Errorf("%w: %s references unknown session %q", ErrBackupInvalid, where, r.SessionID)
691		}
692		// 申请会话必须属于使用账户。
693		if sess.accountID != r.AccountID {
694			return fmt.Errorf("%w: %s session %q belongs to account %q, not usage account %q", ErrBackupInvalid, where, r.SessionID, sess.accountID, r.AccountID)
695		}
696		p, ok := policies[r.PolicyID]
697		if !ok {
698			return fmt.Errorf("%w: %s references unknown policy %q", ErrBackupInvalid, where, r.PolicyID)
699		}
700		// 请求出资账户必须与策略出资账户一致。
701		if r.PayerAccountID != p.payerAccountID {
702			return fmt.Errorf("%w: %s payer account %q does not match policy %q payer %q", ErrBackupInvalid, where, r.PayerAccountID, r.PolicyID, p.payerAccountID)
703		}
704		if _, ok := p.allowedAccounts[r.AccountID]; !ok {
705			return fmt.Errorf("%w: %s usage account %q is not allowed by policy %q", ErrBackupInvalid, where, r.AccountID, r.PolicyID)
706		}
707		return nil
708	}
709	
710	// validateReserveTiming 校验预留计时三元组自洽：duration 必须非负；
711	// duration>0 时 reservedAt 必填且 reserveDeadline 必须等于
712	// reservedAt+duration；duration==0 时 reserveDeadline 必须为零。
713	// reservedAt 是否必填由各状态自行决定（待审批取消的请求两者都没有）。
714	func validateReserveTiming(r *request) error {
715		if r.reserveDuration < 0 {
716			return errors.New("reserve duration must not be negative")
717		}
718		if r.reserveDuration > 0 {
719			if r.reservedAt.IsZero() {
720				return errors.New("reserve duration set but reserved_at is missing")
721			}
722			want := r.reservedAt.Add(r.reserveDuration)
723			if !r.reserveDeadline.Equal(want) {
724				return fmt.Errorf("reserve deadline %v does not match reserved_at+duration %v", r.reserveDeadline, want)
725			}
726		} else if !r.reserveDeadline.IsZero() {
727			return errors.New("reserve deadline set while reserve duration is zero")
728		}
729		return nil
730	}
731	
732	// validateRequestTimingAndState 校验请求状态与其计时/金额字段自洽，并与
733	// 不可变的策略条件、申请会话保持一致，防止任意状态搭配任意时间戳的损坏
734	// 备份。sess 为该请求的申请会话。
735	func validateRequestTimingAndState(r *request, p *policy, sess *session) error {
736		if r.createdAt.IsZero() {
737			return errors.New("request missing created_at")
738		}
739		if r.operation == "" || r.payee == "" {
740			return errors.New("operation and payee are required")
741		}
742		if r.operation != p.operation || r.payee != p.payee {
743			return fmt.Errorf("operation/payee do not match policy %q", p.id)
744		}
745		if r.estimatedFee > p.maxPerRequest {
746			return fmt.Errorf("estimated fee %d exceeds policy per-request limit %d", r.estimatedFee, p.maxPerRequest)
747		}
748		if r.approverAccountID != "" && r.approverAccountID != r.payerAccountID {
749			return fmt.Errorf("approver account %q is not the payer %q", r.approverAccountID, r.payerAccountID)
750		}
751		if r.actualFee > r.estimatedFee {
752			return fmt.Errorf("actual fee %d exceeds estimated fee %d", r.actualFee, r.estimatedFee)
753		}
754	
755		// 申请是否必须走过审批由不可变策略门槛决定：费用严格超过正门槛的请求
756		// 只能来自待审批流程；其余请求只能直接预留。
757		approvalRequired := p.approvalThreshold > 0 && r.estimatedFee > p.approvalThreshold
758		reservedOrigin := !r.reservedAt.IsZero()
759	
760		switch r.state {
761		case RequestReserved, RequestSettled, RequestReservationExpired:
762			// 这三类一定发生过预留。
763			if err := validateReservedOrigin(r, p, approvalRequired, reservedOrigin); err != nil {
764				return err
765			}
766		case RequestPendingApproval, RequestRejected, RequestExpired:
767			// 这三类一定从未预留，且必须来自开启审批的策略。
768			if err := validatePendingOrigin(r, p, approvalRequired, reservedOrigin); err != nil {
769				return err
770			}
771		case RequestCancelled:
772			// 取消可能来自待审批（从未预留）或已预留。
773			if reservedOrigin {
774				if err := validateReservedOrigin(r, p, approvalRequired, true); err != nil {
775					return err
776				}
777			} else {
778				if err := validatePendingOrigin(r, p, approvalRequired, false); err != nil {
779					return err
780				}
781			}
782		default:
783			return fmt.Errorf("unknown state %d", r.state)
784		}
785	
786		switch r.state {
787		case RequestReserved:
788			// 启用超时时 deadline 必须等于 reservedAt + 时长，未启用时为零，
789			// 且不得已记录超时。
790			if err := validateReserveTiming(r); err != nil {
791				return err
792			}
793			if !r.reserveExpiredAt.IsZero() {
794				return errors.New("reserved request must not carry reserve-expired time")
795			}
796			if r.actualFee != 0 || !r.settledAt.IsZero() {
797				return errors.New("reserved request must not be settled")
798			}
799			if r.rejectReason != "" {
800				return errors.New("reserved request must not carry a reject reason")
801			}
802		case RequestSettled:
803			if r.settledAt.IsZero() {
804				return errors.New("settled request missing settled_at")
805			}
806			if !r.reserveExpiredAt.IsZero() {
807				return errors.New("settled request must not carry reserve-expired time")
808			}
809			if r.settledAt.Before(r.reservedAt) {
810				return errors.New("settled_at is before reserved_at")
811			}
812			if err := validateReserveTiming(r); err != nil {
813				return err
814			}
815			if r.rejectReason != "" {
816				return errors.New("settled request must not carry a reject reason")
817			}
818		case RequestCancelled:
819			if r.actualFee != 0 || !r.settledAt.IsZero() {
820				return errors.New("cancelled request must not be settled")
821			}
822			if !r.reserveExpiredAt.IsZero() {
823				return errors.New("cancelled request must not carry reserve-expired time")
824			}
825			if r.rejectReason != "" {
826				return errors.New("cancelled request must not carry a reject reason")
827			}
828			if reservedOrigin {
829				if err := validateReserveTiming(r); err != nil {
830					return err
831				}
832			} else {
833				// 待审批取消：决定时间必填。
834				if r.decidedAt.IsZero() {
835					return errors.New("cancelled-from-pending request missing decided_at")
836				}
837			}
838		case RequestPendingApproval:
839			// 待审批不冻结余额：不得有实际费用，且等待期限必须等于
840			// min(提交+等待时长, 策略结束, 申请会话到期)。
841			if r.actualFee != 0 || !r.settledAt.IsZero() {
842				return errors.New("pending request must not be settled")
843			}
844			if r.waitDeadline.IsZero() {
845				return errors.New("pending request missing wait deadline")
846			}
847			if r.approverAccountID != "" {
848				return errors.New("pending request must not carry an approver")
849			}
850			if r.rejectReason != "" {
851				return errors.New("pending request must not carry a reject reason")
852			}
853			want := r.createdAt.Add(p.approvalWait)
854			if p.endsAt.Before(want) {
855				want = p.endsAt
856			}
857			if sess.expiresAt.Before(want) {
858				want = sess.expiresAt
859			}
860			if !r.waitDeadline.Equal(want) {
861				return fmt.Errorf("wait deadline %v does not match min(created+wait, policy end, session expiry) %v", r.waitDeadline, want)
862			}
863		case RequestRejected:
864			if r.decidedAt.IsZero() || r.rejectReason == "" {
865				return errors.New("rejected request missing decided_at or reason")
866			}
867		case RequestExpired:
868			if r.decidedAt.IsZero() {
869				return errors.New("expired request missing decided_at")
870			}
871			if r.rejectReason != "" {
872				return errors.New("expired request must not carry a reject reason")
873			}
874			// 惰性/停用过期的决定时刻不可能早于等待截止时刻。
875			if r.decidedAt.Before(r.waitDeadline) {
876				return errors.New("expired request decided before its wait deadline")
877			}
878		case RequestReservationExpired:
879			if r.reserveDuration <= 0 {
880				return errors.New("reservation-expired request must have a positive reserve duration")
881			}
882			if err := validateReserveTiming(r); err != nil {
883				return err
884			}
885			if !r.reserveExpiredAt.Equal(r.reserveDeadline) {
886				return errors.New("reserve-expired-at must equal reserve deadline")
887			}
888			if r.actualFee != 0 || !r.settledAt.IsZero() {
889				return errors.New("reservation-expired request must not be settled")
890			}
891			if r.rejectReason != "" {
892				return errors.New("reservation-expired request must not carry a reject reason")
893			}
894		}
895		return nil
896	}
897	
898	// validateReservedOrigin 校验“发生过预留”的请求：预留计时字段必须齐全、
899	// 预留时长快照必须与策略一致，且审批路径（批准人、决定时间）与费用/门槛
900	// 相匹配。对所有发生过预留的状态（已预留、已结算、预留超时、已预留后
901	// 取消）统一适用：超门槛的必须经出资账户在预留时刻批准，未超门槛的直接
902	// 受理、不得携带批准人或决定时间。
903	func validateReservedOrigin(r *request, p *policy, approvalRequired, reservedOrigin bool) error {
904		if !reservedOrigin {
905			return errors.New("request is in a reserved-origin state but missing reserved_at")
906		}
907		if r.reserveDuration != p.maxReserveDuration {
908			return fmt.Errorf("reserve duration %v does not match policy max reserve duration %v", r.reserveDuration, p.maxReserveDuration)
909		}
910		if approvalRequired {
911			if r.approverAccountID != r.payerAccountID {
912				return errors.New("above-threshold request was reserved without payer approval")
913			}
914			if !r.decidedAt.Equal(r.reservedAt) {
915				return errors.New("approved request decided_at must equal reserved_at")
916			}
917		} else {
918			if r.approverAccountID != "" {
919				return errors.New("below-threshold request must not carry an approver")
920			}
921			if !r.decidedAt.IsZero() {
922				return errors.New("directly reserved request must not carry decided_at")
923			}
924		}
925		return nil
926	}
927	
928	// validatePendingOrigin 校验“从未预留”的待审批系请求：不得携带任何预留
929	// 计时字段，且策略必须开启审批、费用必须严格超过门槛。
930	func validatePendingOrigin(r *request, p *policy, approvalRequired, reservedOrigin bool) error {
931		if reservedOrigin {
932			return errors.New("request is in a pending-origin state but carries reserved_at")
933		}
934		if !approvalRequired {
935			return errors.New("request is in an approval state although policy approval is not enabled for its fee")
936		}
937		if !r.reserveDeadline.IsZero() || !r.reserveExpiredAt.IsZero() || r.reserveDuration != 0 {
938			return errors.New("pending-origin request must not carry reserve timing")
939		}
940		return nil
941	}
942

