339	func policyViewsEqual(a, b PolicyView) bool {
340		// AllowedAccountIDs 由 map 生成，顺序不稳定；按集合比较。
341		aAllowed := append([]string(nil), a.AllowedAccountIDs...)
342		bAllowed := append([]string(nil), b.AllowedAccountIDs...)
343		sort.Strings(aAllowed)
344		sort.Strings(bAllowed)
345		if len(aAllowed) != len(bAllowed) {
346			return false
347		}
348		for i := range aAllowed {
349			if aAllowed[i] != bAllowed[i] {
350				return false
351			}
352		}
353		a.AllowedAccountIDs, b.AllowedAccountIDs = nil, nil
354		// PolicySpec 含切片字段，不能直接用 != 比较；逐字段核对。
355		if a.ID != b.ID || a.PayerAccountID != b.PayerAccountID ||
356			a.Operation != b.Operation || a.Payee != b.Payee ||
357			!a.StartsAt.Equal(b.StartsAt) || !a.EndsAt.Equal(b.EndsAt) ||
358			a.MaxPerRequest != b.MaxPerRequest || a.MaxTotal != b.MaxTotal ||
359			a.ApprovalThreshold != b.ApprovalThreshold || a.ApprovalWait != b.ApprovalWait ||
360			a.MaxReserveDuration != b.MaxReserveDuration {
361			return false
362		}
363		return a.ReservedTotal == b.ReservedTotal && a.SpentTotal == b.SpentTotal &&
364			a.Deactivated == b.Deactivated && a.DeactivatedAt.Equal(b.DeactivatedAt) &&
365			a.DeactivatorAccountID == b.DeactivatorAccountID && a.DeactivateReason == b.DeactivateReason
366	}
367	
368	func requestViewsEqual(a, b RequestView) bool {
369		return a.PolicyID == b.PolicyID && a.RequestID == b.RequestID && a.AccountID == b.AccountID &&
370			a.PayerAccountID == b.PayerAccountID && a.Operation == b.Operation && a.Payee == b.Payee &&
371			a.EstimatedFee == b.EstimatedFee && a.ActualFee == b.ActualFee && a.State == b.State &&
372			a.CreatedAt.Equal(b.CreatedAt) && a.SettledAt.Equal(b.SettledAt) &&
373			a.WaitDeadline.Equal(b.WaitDeadline) && a.ReservedAt.Equal(b.ReservedAt) &&
374			a.ReserveDuration == b.ReserveDuration && a.ReserveDeadline.Equal(b.ReserveDeadline) &&
375			a.ReserveExpiredAt.Equal(b.ReserveExpiredAt) && a.DecidedAt.Equal(b.DecidedAt) &&
376			a.ApproverAccountID == b.ApproverAccountID && a.RejectReason == b.RejectReason
377	}
