923					}
924				}
925			}},
926			{"ledger references unknown policy", func(m map[string]interface{}) {
927				l := m["ledger"].([]interface{})
928				l[0].(map[string]interface{})["policy_id"] = "p-ghost"
929			}},
930			{"non-positive estimated fee", func(m map[string]interface{}) {
931				m["requests"].([]interface{})[0].(map[string]interface{})["estimated_fee"] = 0
932			}},
933			{"actual fee exceeds estimated", func(m map[string]interface{}) {
934				for _, r := range m["requests"].([]interface{}) {
935					rm := r.(map[string]interface{})
936					if rm["request_id"] == "settled" {
937						rm["actual_fee"] = 99
938					}
939				}
940			}},
941		}
942		for _, tc := range cases {
943			t.Run(tc.name, func(t *testing.T) {
944				m := mustMap(t, good)
945				tc.mutate(m)
946				w2, err := Restore(mustRemap(t, m))
947				if err == nil {
948					if w2 != nil {
949						t.Fatalf("corrupt backup %q restored a wallet", tc.name)
950					}
951					t.Fatalf("corrupt backup %q restored without error", tc.name)
952				}
953				if !errors.Is(err, ErrBackupInvalid) {
954					t.Fatalf("corrupt backup %q err = %v, want ErrBackupInvalid", tc.name, err)
955				}
956			})
957		}
958	
959		// 文本级损坏。
960		for _, tc := range []struct {
961			name string
962			data []byte
963		}{
964			{"empty", []byte("")},
965			{"whitespace", []byte("   \n\t ")},
966			{"malformed", []byte("{not json")},
967			{"not an object", []byte(`[1,2,3]`)},
968			{"trailing value", append(append([]byte{}, good...), []byte(" {}")...)},
969		} {
970			t.Run(tc.name, func(t *testing.T) {
971				w2, err := Restore(tc.data)
972				if err == nil || w2 != nil {
973					t.Fatalf("corrupt text %q: w2=%v err=%v", tc.name, w2, err)
974				}
975				if !errors.Is(err, ErrBackupInvalid) {
976					t.Fatalf("corrupt text %q err = %v", tc.name, err)
977				}
978			})
979		}
980	}
981	
982	func TestRestoreRejectsInt64Overflow(t *testing.T) {
983		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
984		b := backupV1{
985			Version:    backupVersion,
986			ExportedAt: timeJSON(t0),
987			Accounts: []accountBackupV1{
988				{ID: "payer", Available: 0, Reserved: math.MaxInt64, CreatedAt: timeJSON(t0)},
989				{ID: "u1", Available: 0, Reserved: 0, CreatedAt: timeJSON(t0)},
990			},
991			Sessions: []sessionBackupV1{
992				{ID: "s1", AccountID: "u1", DeviceID: "d1", ExpiresAt: timeJSON(t0.Add(time.Hour)), CreatedAt: timeJSON(t0)},
993			},
994			Policies: []policyBackupV1{{
995				ID: "p", PayerAccountID: "payer", AllowedAccountIDs: []string{"u1"},
996				Operation: "charge", Payee: "shop",
997				StartsAt: timeJSON(t0.Add(-time.Hour)), EndsAt: timeJSON(t0.Add(time.Hour)),
998				MaxPerRequest: math.MaxInt64, MaxTotal: math.MaxInt64,
999				ReservedTotal: math.MaxInt64,
1000			}},
1001			Requests: []requestBackupV1{
1002				{
1003					PolicyID: "p", RequestID: "r1", AccountID: "u1", PayerAccountID: "payer",
1004					SessionID: "s1", Operation: "charge", Payee: "shop",
1005					EstimatedFee: math.MaxInt64, State: int(RequestReserved),
1006					CreatedAt: timeJSON(t0), ReservedAt: timeJSON(t0),
1007				},
1008				{
1009					PolicyID: "p", RequestID: "r2", AccountID: "u1", PayerAccountID: "payer",
1010					SessionID: "s1", Operation: "charge", Payee: "shop",
1011					EstimatedFee: math.MaxInt64, State: int(RequestReserved),
1012					CreatedAt: timeJSON(t0), ReservedAt: timeJSON(t0),
1013				},
1014			},
1015			Ledger: []ledgerEntryBackupV1{},
1016		}
1017		data, err := json.Marshal(&b)
1018		if err != nil {
1019			t.Fatal(err)
1020		}
1021		if _, err := Restore(data); err == nil {
1022			t.Fatal("overflow backup restored")
1023		} else if !errors.Is(err, ErrBackupInvalid) {
1024			t.Fatalf("overflow err = %v, want ErrBackupInvalid", err)
1025		}
1026	}
1027	
1028	// ---- 并发 ----
1029	
1030	func TestExportConcurrentWithMutations(t *testing.T) {
1031		w, c := newTestWallet()
1032		t0 := c.t
1033		mustAccount(t, w, "payer", 1_000_000)
1034		mustAccount(t, w, "u1", 0)
1035		mustAccount(t, w, "u2", 0)
1036		if _, err := w.CreateSession("s1", "u1", "dev1", t0.Add(24*time.Hour)); err != nil {
1037			t.Fatal(err)
1038		}
1039		if _, err := w.CreateSession("s2", "u2", "dev2", t0.Add(24*time.Hour)); err != nil {
1040			t.Fatal(err)
1041		}
1042		if err := w.SavePolicy(PolicySpec{
1043			ID: "p1", PayerAccountID: "payer", AllowedAccountIDs: []string{"u1", "u2"},
1044			Operation: "charge", Payee: "shop",
1045			StartsAt: t0.Add(-time.Hour), EndsAt: t0.Add(24 * time.Hour),
1046			MaxPerRequest: 100, MaxTotal: 1_000_000,
1047			MaxReserveDuration: time.Hour,
1048		}); err != nil {
1049			t.Fatal(err)
1050		}
1051	
1052		const n = 200
1053		var wg sync.WaitGroup
1054		var backups [][]byte
1055		var mu sync.Mutex
1056	
1057		// 申请/结算/取消/导出 并发；每个备份都必须是可恢复的完整状态。
1058		for g := 0; g < 4; g++ {
1059			g := g
1060			wg.Add(1)
1061			go func() {
1062				defer wg.Done()
1063				for i := 0; i < n; i++ {
1064					rid := fmt.Sprintf("g%d-r%d", g, i)
1065					in := RequestInput{
1066						PolicyID: "p1", RequestID: rid, AccountID: "u2", SessionID: "s2",
1067						DeviceID: "dev2", Operation: "charge", Payee: "shop", EstimatedFee: 1,
1068					}
1069					if _, err := w.Apply(in); err != nil {
1070						t.Errorf("apply: %v", err)
1071						return
1072					}
1073					switch i % 3 {
1074					case 0:
1075						if _, err := w.Settle("u2", rid, 1); err != nil {
1076							t.Errorf("settle: %v", err)
1077						}
1078					case 1:
1079						if _, err := w.Cancel("u2", rid); err != nil {
1080							t.Errorf("cancel: %v", err)
1081						}
1082					}
1083				}
1084			}()
1085		}
1086		wg.Add(1)
1087		go func() {
1088			defer wg.Done()
1089			for i := 0; i < n; i++ {
1090				data, err := w.Export()
1091				if err != nil {
1092					t.Errorf("export: %v", err)
1093					return
1094				}
1095				mu.Lock()
1096				backups = append(backups, data)
1097				mu.Unlock()
1098			}
1099		}()
1100		wg.Wait()
1101	
1102		if len(backups) == 0 {
1103			t.Fatal("no backups captured")
1104		}
1105		for i, data := range backups {
1106			w2, err := Restore(data)
1107			if err != nil {
1108				t.Fatalf("backup %d not restorable: %v", i, err)
1109			}
1110			// 恢复出的钱包余额自洽：非负且预留不凭空消失。
1111			for _, id := range []string{"payer"} {
1112				bal, err := w2.Balance(id)
1113				if err != nil {
1114					t.Fatalf("backup %d balance: %v", i, err)
1115				}
1116				if bal.Available < 0 || bal.Reserved < 0 {
1117					t.Fatalf("backup %d negative balance: %+v", i, bal)
1118				}
1119			}
1120		}
1121	
1122		// 最终状态本身也必须可导出/恢复且账本完整（用与源钱包相同的受控时刻，
1123		// 避免恢复时钟把未到期预留结算掉而混淆比较）。
1124		final, err := w.Export()
1125		if err != nil {
1126			t.Fatal(err)
1127		}
1128		w2, err := restoreAt(final, c.t)
1129		if err != nil {
1130			t.Fatal(err)
1131		}
1132		if l1, l2 := len(w.Ledger()), len(w2.Ledger()); l1 != l2 {
1133			t.Fatalf("final ledger length = %d, want %d", l2, l1)
1134		}
1135	}
