		t.Fatalf("balance = %+v, historical fees must not count as reserved", bal)
	}
	if r, err := w.Request("u1", "r-pending"); err != nil || r.State != RequestPendingApproval {
		t.Fatalf("pending request = %+v err = %v", r, err)
	}
}

